(function(outputs, steps, params, stepResult, assertEqual) {

    describe("DirectoryMemberAPI - validateContent tests", () => {
        const api = new x_neyu_google_nyu.DirectoryMemberAPI();

        it("should return an array of missing required keys", () => {
            const spec = {
                keyA: {
                    required: true
                },
                keyB: {
                    required: false
                }
            };
            const content = {
                keyB: "something"
            };
            const result = api.validateContent(spec, content);
            expect(result).toBeDefined();
            expect(result.length).toBe(1);
            expect(result[0]).toEqual("keyA");
        });

        it("should have the hasToken method extended from AuthUtil", () => {
            expect("ensureToken" in api).toBe(true);
        });

        it("Should return an error if a input value is not in the spec's enum", () => {
            const spec = {
                keyA: {
                    required: true,
                    enum: ["a", "b"]
                }
            };
            const content = {
                keyA: "c"
            };

            const result = api.validateContent(spec, content);
            expect(result).toBeDefined();
            expect(result).toEqual({
                keyA: "c"
            });
        });

        it("should return null if all conditions are satified", () => {
            const spec = {
                keyA: {
                    required: true,
                    enum: ["a", "b"]
                },
                keyB: {
                    required: true
                }
            };
            const content = {
                keyA: "a",
                keyB: "foo"
            };

            expect(api.validateContent(spec, content)).toBe(null);
        });

		it("should return an error if there are extra inputs.", () => {

		});

    });

})(outputs, steps, params, stepResult, assertEqual);
// uncomment the next line to execute this script as a jasmine test
jasmine.getEnv().execute();
